sys_hub_input_scripts.script:
{"variable":{"scriptActive":true,"script":"var ritmSysId = fd_data.trigger.request_item.sys_id;
var reqItem = new GlideRecord('sc_req_item');

var requestedMonth = '';
var requestedYear = '';

if(reqItem.get(ritmSysId)){
 requestedMonth = reqItem.variables.month_of_the_invoice + '';
 requestedYear = reqItem.variables.which_year + '';
};

requestedMonth = Number(requestedMonth) +1 ;
requestedYear = Number(requestedYear);

if(requestedMonth < 10){
 requestedMonth = '0' + requestedMonth;
};

var dateOfReqItem = '01.' + requestedMonth + '.' + requestedYear;

return dateOfReqItem;"}}

